{
  "items": [
    {
      "name": "Finsupp.weight_eq_zero_iff_eq_zero",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {M : Type u_4} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedAddMonoid M]\n  [CanonicallyOrderedAdd M] (w : σ → M) [Finsupp.NonTorsionWeight ℕ w] {f : σ →₀ ℕ}, (Finsupp.weight w) f = 0 ↔ f = 0"
    },
    {
      "name": "MvPolynomial.weightedDegree_eq_zero_iff",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {M : Type u_2} {σ : Type u_3} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] {w : σ → M}\n  [CanonicallyOrderedAdd M],\n  MvPolynomial.NonTorsionWeight w → ∀ {m : σ →₀ ℕ}, (Finsupp.weight w) m = 0 ↔ ∀ (x : σ), m x = 0"
    },
    {
      "name": "Finsupp.support_eq_empty",
      "module_name": "Mathlib.Data.Finsupp.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_4} [inst : Zero M] {f : α →₀ M}, f.support = ∅ ↔ f = 0"
    },
    {
      "name": "Finsupp.coe_eq_zero",
      "module_name": "Mathlib.Data.Finsupp.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_4} [inst : Zero M] {f : α →₀ M}, ⇑f = 0 ↔ f = 0"
    },
    {
      "name": "Finsupp",
      "module_name": "Mathlib.Data.Finsupp.Defs",
      "kind": "inductive",
      "type": "Type u_9 → (M : Type u_10) → [Zero M] → Type (max u_10 u_9)"
    },
    {
      "name": "DFinsupp.mem_support_iff",
      "module_name": "Mathlib.Data.DFinsupp.Defs",
      "kind": "theorem",
      "type": "∀ {ι : Type u} {β : ι → Type v} [inst : DecidableEq ι] [inst_1 : (i : ι) → Zero (β i)]\n  [inst_2 : (i : ι) → (x : β i) → Decidable (x ≠ 0)] {f : Π₀ (i : ι), β i} {i : ι}, i ∈ f.support ↔ f i ≠ 0"
    },
    {
      "name": "Finsupp.degree_eq_zero_iff",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_5} [inst : AddCommMonoid R] [inst_1 : PartialOrder R] [CanonicallyOrderedAdd R]\n  (d : σ →₀ R), Finsupp.degree d = 0 ↔ d = 0"
    },
    {
      "name": "Finsupp.add_eq_zero_iff",
      "module_name": "Mathlib.Data.Finsupp.Order",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : Type u_3} [inst : AddCommMonoid α] [inst_1 : PartialOrder α] [CanonicallyOrderedAdd α]\n  (f g : ι →₀ α), f + g = 0 ↔ f = 0 ∧ g = 0"
    }
  ]
}

